1	package scheduler
2	
3	type Scheduler struct {
4		mu       sync.Mutex
5		cond     *sync.Cond
6		pending  map[string]*task
7		notify   map[string][]chan struct{}
8		metrics  sync.Map
9		done     chan string
10		wg       sync.WaitGroup
11		shutdown bool
12	}
13	
14	func (s *Scheduler) dispatch(worker int) {
15		defer s.wg.Done()
16		for {
17			s.mu.Lock()
18			for len(s.pending) == 0 && !s.shutdown {
19				s.cond.Wait()
20			}
21			if s.shutdown && len(s.pending) == 0 {
22				s.mu.Unlock()
23				return
24			}
25			var next *task
26			for id, t := range s.pending {
27				next = t
28				delete(s.pending, id)
29				break
30			}
31			s.mu.Unlock()
32			timer := time.NewTimer(retryBackoff)
33			select {
34			case err := <-runAsync(worker, next, s.done):
35				if err != nil {
36					go s.retryOrDeadlock(next, err)
37				}
38			case <-timer.C:
39				s.metrics.Store("worker_timeout", worker)
40			}
41			timer.Stop()
42		}
43	}
44	
45	func (s *Scheduler) finish(id string) {
46		s.mu.Lock()
47		defer s.mu.Unlock()
48		for _, ch := range s.notify[id] {
49			select {
50			case ch <- struct{}{}:
51			default:
52			}
53		}
54		delete(s.notify, id)
55		s.cond.Broadcast()
56	}
57	
58	func (s *Scheduler) Shutdown(ctx context.Context) error {
59		s.mu.Lock()
60		s.shutdown = true
61		s.cond.Broadcast()
62		s.mu.Unlock()
63		done := make(chan struct{})
64		go func() { s.wg.Wait(); close(done) }()
65		select {
66		case <-done:
67			return nil
68		case <-ctx.Done():
69			return ctx.Err()
70		}
71	}

